import '../../src/styles/index.css';import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';import {BrowserRouter} from 'react-router-dom';import {UIProvider} from '../../src/context/UIContext.jsx';
import EternalTemplate from '../../src/components/templates/eternal/EternalTemplate.jsx';import NawasenaTemplate from '../../src/components/templates/nawasena/NawasenaTemplate.jsx';import SerayaTemplate from '../../src/components/templates/seraya/SerayaTemplate.jsx';
const components={eternal:EternalTemplate,nawasena:NawasenaTemplate,seraya:SerayaTemplate};
const media=['garden','rosewalk','twilight','garden','rosewalk','twilight'].map((name,index)=>({id:`img-${index}`,type:'photo',url:`/assets/landing-canvas/${name}.webp`,order:index}));media.push({id:'video',type:'video',url:'/assets/gallery/dummy-gallery-video.mp4',order:6});
function App(){const [theme,setTheme]=useState('seraya'),[layout,setLayout]=useState('wall'),ref=useRef(null);const Component=components[theme];const invitation={id:'standard-gallery-check',themeId:theme,weddingDate:'2027-12-20',coupleProfile:{brideName:'A',groomName:'B'},themeSettings:{galleryLayout:layout},galleryMedia:media,events:[],invitationFeatures:{galleryEnabled:true}};
function show(){const gallery=ref.current.querySelector('[data-section="gallery"],#gallery');gallery?.scrollIntoView({block:'start',behavior:'instant'})}
return <div style={{padding:16}}><h1 style={{fontSize:24}}>Standar galeri · data uji</h1><div style={{display:'flex',gap:10,marginBottom:12}}>{Object.keys(components).map(name=><button key={name} onClick={()=>setTheme(name)}>{name}</button>)}<select aria-label="Layout" value={layout} onChange={e=>setLayout(e.target.value)}>{['editorial','grid','masonry','carousel','collage','wall'].map(name=><option key={name}>{name}</option>)}</select><button onClick={show}>Lihat galeri</button></div><div ref={ref} style={{position:'relative',width:390,height:844,overflow:'hidden',border:'1px solid #78866b'}}><Component key={theme} invitation={invitation} editorPreview/></div></div>}
createRoot(document.getElementById('root')).render(<BrowserRouter><UIProvider><App/></UIProvider></BrowserRouter>);
